diff --git a/pilot-task/src/normalize-email.mjs b/pilot-task/src/normalize-email.mjs
index 37219ea..219a4d5 100644
--- a/pilot-task/src/normalize-email.mjs
+++ b/pilot-task/src/normalize-email.mjs
@@ -1,3 +1,36 @@
 export function normalizeEmail(value) {
-  return String(value).trim().toLowerCase();
+  if (typeof value !== 'string') {
+    throw new TypeError('Email address must be a string');
+  }
+
+  const email = value.trim();
+
+  if (email.length === 0 || email.length > 254 || /\s/u.test(email)) {
+    throw new TypeError('Invalid email address');
+  }
+
+  const separator = email.indexOf('@');
+  if (separator <= 0 || separator !== email.lastIndexOf('@') || separator === email.length - 1) {
+    throw new TypeError('Invalid email address');
+  }
+
+  const localPart = email.slice(0, separator);
+  const domain = email.slice(separator + 1);
+  const localPartPattern = /^[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+(?:\.[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+)*$/u;
+  const domainLabels = domain.split('.');
+
+  if (
+    localPart.length > 64
+    || !localPartPattern.test(localPart)
+    || domain.length > 253
+    || domainLabels.some((label) => (
+      label.length === 0
+      || label.length > 63
+      || !/^[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?$/u.test(label)
+    ))
+  ) {
+    throw new TypeError('Invalid email address');
+  }
+
+  return `${localPart}@${domain.toLowerCase()}`;
 }
